#pragma once
// Generic production chat calls. Rust owns all inputs, control flow and assertions.
#include "chat_parser.hpp"
#include "tools/server/server-chat.h"
#include "tools/server/server-common.h"
#include <chrono>
#include <regex>

namespace prism_chat {
using json=nlohmann::ordered_json;
using prism_peg::require;using prism_peg::fields;using prism_peg::string;using prism_peg::integer;
inline bool handles(const std::string & kind){return kind=="chat-trace"||kind=="chat-value"||kind=="chat-server-params"||kind=="chat-generic-parse"||kind=="chat-regex";}
inline std::string bytes(const json & x){require(x.is_array()&&x.size()<=1024*1024,"chat byte input exceeds bound");std::string s;for(const auto & v:x){integer(v,0,255);s.push_back(static_cast<char>(v.get<unsigned>()));}return s;}
inline common_json raw(const json & x){string(x,4*1024*1024);return common_json::parse(x.get<std::string>());}
inline common_chat_tool_call call(const json & x){return {x.at("name").get<std::string>(),x.at("arguments").get<std::string>(),x.at("id").get<std::string>()};}
inline common_chat_msg message(const json & x){common_chat_msg m;m.role=x.at("role").get<std::string>();m.content=x.at("content").get<std::string>();m.reasoning_content=x.at("reasoning_content").get<std::string>();m.tool_name=x.at("tool_name").get<std::string>();m.tool_call_id=x.at("tool_call_id").get<std::string>();for(const auto & p:x.at("content_parts"))m.content_parts.push_back({p.at("type").get<std::string>(),p.at("text").get<std::string>()});for(const auto & c:x.at("tool_calls"))m.tool_calls.push_back(call(c));return m;}
inline json message(const common_chat_msg & m){json parts=json::array(),calls=json::array();for(const auto & p:m.content_parts)parts.push_back({{"type",p.type},{"text",p.text}});for(const auto & c:m.tool_calls)calls.push_back({{"name",c.name},{"arguments",c.arguments},{"id",c.id}});return {{"role",m.role},{"content",m.content},{"content_parts",parts},{"tool_calls",calls},{"reasoning_content",m.reasoning_content},{"tool_name",m.tool_name},{"tool_call_id",m.tool_call_id}};}
inline std::vector<common_chat_msg> messages(const json & x){require(x.is_array()&&x.size()<=1024,"chat message count exceeds bound");std::vector<common_chat_msg> out;for(const auto & m:x)out.push_back(message(m));return out;}
inline std::vector<common_chat_tool> tools(const json & x){require(x.is_array()&&x.size()<=1024,"chat tool count exceeds bound");std::vector<common_chat_tool> out;for(const auto & t:x)out.push_back({t.at("name").get<std::string>(),t.at("description").get<std::string>(),t.at("parameters").get<std::string>()});return out;}
inline json diffs(const std::vector<common_chat_msg_diff> & values){json out=json::array();for(const auto & d:values)out.push_back({{"reasoning_content_delta",d.reasoning_content_delta},{"content_delta",d.content_delta},{"tool_call_index",d.tool_call_index==std::string::npos?json(nullptr):json(d.tool_call_index)},{"tool_call_delta",{{"name",d.tool_call_delta.name},{"arguments",d.tool_call_delta.arguments},{"id",d.tool_call_delta.id}}}});return out;}
inline common_chat_templates_inputs inputs(const json & encoded){const auto x=raw(encoded);require(x.is_object(),"chat inputs must be object");common_chat_templates_inputs p;for(const auto & item:x.items()){const auto k=item.key();const auto v=json::parse(item.value().dump());if(k=="messages")p.messages=messages(v);else if(k=="tools")p.tools=tools(v);else if(k=="add_generation_prompt")p.add_generation_prompt=v.get<bool>();else if(k=="continue_final_message"){integer(v,0,3);p.continue_final_message=static_cast<common_chat_continuation>(v.get<int>());}else if(k=="use_jinja")p.use_jinja=v.get<bool>();else if(k=="tool_choice"){integer(v,0,2);p.tool_choice=static_cast<common_chat_tool_choice>(v.get<int>());}else if(k=="parallel_tool_calls")p.parallel_tool_calls=v.get<bool>();else if(k=="reasoning_format"){integer(v,0,3);p.reasoning_format=static_cast<common_reasoning_format>(v.get<int>());}else if(k=="enable_thinking")p.enable_thinking=v.get<bool>();else if(k=="grammar")p.grammar=v.get<std::string>();else if(k=="json_schema")p.json_schema=v.get<std::string>();else if(k=="chat_template_kwargs"){for(const auto & kw:v.items())p.chat_template_kwargs[kw.key()]=kw.value().get<std::string>();}else if(k=="now_milliseconds"){integer(v,0,4102444800000LL);p.now=std::chrono::system_clock::time_point(std::chrono::milliseconds(v.get<int64_t>()));}else throw std::runtime_error("unknown chat input parameter");}return p;}
inline json parameters(const common_chat_params & p){json triggers=json::array();for(const auto & t:p.grammar_triggers)triggers.push_back({{"type",static_cast<int>(t.type)},{"value",t.value}});return{{"format",static_cast<int>(p.format)},{"prompt",p.prompt},{"grammar",p.grammar},{"grammar_lazy",p.grammar_lazy},{"generation_prompt",p.generation_prompt},{"supports_thinking",p.supports_thinking},{"thinking_start_tag",p.thinking_start_tag},{"thinking_end_tags",p.thinking_end_tags},{"grammar_triggers",triggers},{"parser",p.parser}};}
inline void validate(const json & op){const auto kind=op.at("Kind").get<std::string>();require(handles(kind),"unknown chat operation");if(kind=="chat-trace"){fields(op,{"Kind","Template","Actions"});string(op.at("Template"),1024*1024);const auto & actions=op.at("Actions");require(actions.is_array()&&actions.size()<=32768,"chat action count exceeds bound");bool applied=false;std::set<int> stored;for(const auto & a:actions){const auto k=a.at("Kind").get<std::string>();if(k=="apply"){fields(a,{"Kind","ParametersJson"});(void)inputs(a.at("ParametersJson"));applied=true;}else if(k=="caps")fields(a,{"Kind"});else if(k=="parse"){fields(a,{"Kind","Bytes","Partial","Store"});require(applied,"chat parse requires apply");(void)bytes(a.at("Bytes"));require(a.at("Partial").is_boolean(),"partial must be boolean");integer(a.at("Store"),0,32767);require(stored.insert(a.at("Store").get<int>()).second,"duplicate chat message handle");}else if(k=="diff"){fields(a,{"Kind","Before","After"});integer(a.at("After"),0,32767);require(stored.count(a.at("After").get<int>())!=0,"unknown after message handle");if(!a.at("Before").is_null()){integer(a.at("Before"),0,32767);require(stored.count(a.at("Before").get<int>())!=0,"unknown before message handle");}}else throw std::runtime_error("unknown chat action");}return;}
 if(kind=="chat-regex"){fields(op,{"Kind","Patterns","Actions"});require(op.at("Patterns").is_array()&&op.at("Patterns").size()<=128,"regex pattern count exceeds bound");for(const auto & p:op.at("Patterns"))string(p,65536);const auto & actions=op.at("Actions");require(actions.is_array()&&actions.size()<=32768,"regex action count exceeds bound");for(const auto & a:actions){fields(a,{"Pattern","Function","Bytes"});integer(a.at("Pattern"),0,127);require(a.at("Pattern").get<size_t>()<op.at("Patterns").size(),"regex pattern index invalid");const auto fn=a.at("Function").get<std::string>();require(fn=="search"||fn=="match","unknown regex function");(void)bytes(a.at("Bytes"));}return;}
 if(kind=="chat-generic-parse"){fields(op,{"Kind","Bytes","Partial"});(void)bytes(op.at("Bytes"));require(op.at("Partial").is_boolean(),"partial must be boolean");return;}
 if(kind=="chat-server-params"){fields(op,{"Kind","Template","Options","BodyJson"});string(op.at("Template"),1024*1024);(void)raw(op.at("BodyJson"));const auto & o=op.at("Options");require(o.is_object()&&o.size()<=5,"server options exceed bound");for(const auto & i:o.items())require(i.key()=="use_jinja"||i.key()=="enable_thinking"||i.key()=="reasoning_budget"||i.key()=="reasoning_format"||i.key()=="reasoning_budget_message","unknown server option");return;}
 const auto fn=op.at("Function").get<std::string>();if(fn=="messages-to-oai"){fields(op,{"Kind","Function","Values"});(void)messages(op.at("Values"));}else if(fn=="tools-to-oai"){fields(op,{"Kind","Function","Values"});(void)tools(op.at("Values"));}else if(fn=="messages-from-oai"||fn=="tools-from-oai"||fn=="convert-responses"){fields(op,{"Kind","Function","Json"});(void)raw(op.at("Json"));}else if(fn=="diff"){fields(op,{"Kind","Function","Before","After"});(void)message(op.at("Before"));(void)message(op.at("After"));}else if(fn=="delimiter-split"){fields(op,{"Kind","Function","Delimiters","Tokens","Skips"});require(op.at("Delimiters").is_array()&&op.at("Delimiters").size()<=1024,"delimiter count exceeds bound");require(op.at("Tokens").is_array()&&op.at("Tokens").size()<=65536,"token count exceeds bound");for(const auto & t:op.at("Tokens"))integer(t,-1,INT32_MAX);for(const auto & d:op.at("Delimiters")){fields(d,{"Role","Delimiter","Tokens"});integer(d.at("Role"),0,4);string(d.at("Delimiter"),65536);require(d.at("Tokens").is_array()&&d.at("Tokens").size()<=1024,"delimiter tokens exceed bound");for(const auto & t:d.at("Tokens"))integer(t,-1,INT32_MAX);}require(op.at("Skips").is_array()&&op.at("Skips").size()<=1024,"skip count exceeds bound");for(const auto & skip:op.at("Skips")){require(skip.is_array()&&skip.size()==2,"invalid skip pair");integer(skip[0],0,65536);integer(skip[1],0,65536);}}else throw std::runtime_error("unknown chat value function");}
inline json error(const char * kind,const std::string & message){return{{"ExceptionKind",kind},{"Message",message}};}
inline json execute(const json & op){const auto kind=op.at("Kind").get<std::string>();if(kind=="chat-regex"){std::vector<std::regex> patterns;for(const auto & p:op.at("Patterns"))patterns.emplace_back(p.get<std::string>());json trace=json::array();for(const auto & a:op.at("Actions")){const auto & pattern=patterns.at(a.at("Pattern").get<size_t>());const auto input=bytes(a.at("Bytes"));std::smatch match;const bool matched=a.at("Function")=="search"?std::regex_search(input,match,pattern):std::regex_match(input,match,pattern);json captures=json::array();if(matched)for(size_t i=0;i<match.size();++i)captures.push_back({{"Position",match.position(i)},{"Length",match.length(i)}});trace.push_back({{"Matched",matched},{"MarkCount",pattern.mark_count()},{"Captures",captures}});}return{{"Trace",trace}};}
 if(kind=="chat-trace"){auto tmpls=common_chat_templates_init(nullptr,op.at("Template").get<std::string>());common_chat_params params;common_peg_arena arena;bool loaded=false;std::map<int,common_chat_msg> stored;json trace=json::array();for(const auto & a:op.at("Actions")){const auto k=a.at("Kind").get<std::string>();if(k=="apply"){params=common_chat_templates_apply(tmpls.get(),inputs(a.at("ParametersJson")));loaded=false;trace.push_back(parameters(params));}else if(k=="caps"){json caps=json::object();for(const auto & cap:common_chat_templates_get_caps(tmpls.get()))caps[cap.first]=cap.second;trace.push_back({{"Caps",caps}});}else if(k=="parse"){json item;try{if(!loaded){arena.load(params.parser);loaded=true;}common_chat_parser_params pp(params);auto m=common_chat_peg_parse(arena,bytes(a.at("Bytes")),a.at("Partial").get<bool>(),pp);stored.emplace(a.at("Store").get<int>(),m);item={{"ExceptionKind",nullptr},{"Message",message(m)}};}catch(const std::out_of_range & e){item=error("out-of-range",e.what());}catch(const std::runtime_error & e){item=error("runtime",e.what());}catch(const std::exception & e){item=error("standard",e.what());}catch(...){item=error("unknown","");}trace.push_back(item);}else{common_chat_msg before;before.role="assistant";if(!a.at("Before").is_null())before=stored.at(a.at("Before").get<int>());const auto after=stored.at(a.at("After").get<int>());trace.push_back({{"Diffs",diffs(common_chat_msg_diff::compute_diffs(before,after))}});}}return{{"Trace",trace}};}
 if(kind=="chat-generic-parse"){common_chat_parser_params p;return{{"Message",message(common_chat_parse(bytes(op.at("Bytes")),op.at("Partial").get<bool>(),p))}};}
 if(kind=="chat-server-params"){server_chat_params p{};p.tmpls=common_chat_templates_init(nullptr,op.at("Template").get<std::string>());const auto & o=op.at("Options");if(o.contains("use_jinja"))p.use_jinja=o.at("use_jinja").get<bool>();if(o.contains("enable_thinking"))p.enable_thinking=o.at("enable_thinking").get<bool>();if(o.contains("reasoning_budget"))p.reasoning_budget=o.at("reasoning_budget").get<int>();if(o.contains("reasoning_format"))p.reasoning_format=static_cast<common_reasoning_format>(o.at("reasoning_format").get<int>());if(o.contains("reasoning_budget_message"))p.reasoning_budget_message=o.at("reasoning_budget_message").get<std::string>();auto body=raw(op.at("BodyJson"));std::vector<raw_buffer> files;return{{"Value",json::parse(oaicompat_chat_params_parse(body,p,files).dump())}};}
 const auto fn=op.at("Function").get<std::string>();if(fn=="messages-to-oai")return{{"JsonDump",common_chat_msgs_to_json_oaicompat(messages(op.at("Values"))).dump(2)}};
 if(fn=="tools-to-oai")return{{"JsonDump",common_chat_tools_to_json_oaicompat(tools(op.at("Values"))).dump(2)}};
 if(fn=="messages-from-oai"){try{json out=json::array();for(const auto & m:common_chat_msgs_parse_oaicompat(raw(op.at("Json"))))out.push_back(message(m));return{{"ExceptionKind",nullptr},{"Message",""},{"Messages",out}};}catch(const std::exception & e){return error("standard",e.what());}}
 if(fn=="tools-from-oai"){json out=json::array();for(const auto & t:common_chat_tools_parse_oaicompat(raw(op.at("Json"))))out.push_back({{"name",t.name},{"description",t.description},{"parameters",t.parameters}});return{{"Tools",out}};}
 if(fn=="convert-responses")return{{"Value",json::parse(server_chat_convert_responses_to_chatcmpl(raw(op.at("Json"))).dump())}};
 if(fn=="diff")return{{"Diffs",diffs(common_chat_msg_diff::compute_diffs(message(op.at("Before")),message(op.at("After"))))}};
 common_chat_msg_delimiters d;for(const auto & v:op.at("Delimiters"))d.delimiters.push_back({static_cast<common_chat_role>(v.at("Role").get<int>()),v.at("Delimiter").get<std::string>(),v.at("Tokens").get<llama_tokens>()});std::map<size_t,size_t> skips;for(const auto & s:op.at("Skips"))skips.emplace(s[0].get<size_t>(),s[1].get<size_t>());const auto split=d.split(op.at("Tokens").get<llama_tokens>(),skips);json spans=json::array();for(const auto & s:split.spans)spans.push_back({{"role",static_cast<int>(s.role)},{"pos",s.pos},{"len",s.len}});return{{"spans",spans}};
}
} // namespace prism_chat
